const CLOSINGS = Object.freeze({
  money: "This is general education, not financial, tax or legal advice, and I am not a licensed financial adviser. It does not replace a nonprofit credit counselor, a tax professional or a licensed investment professional who knows your situation. Rules and figures change, so confirm on the official pages.",
  general: "I am not a financial adviser, lawyer or tax professional, I never move or invest your money, and rules change, so please confirm anything that matters on the official pages."
});

// The ideas in these topics hold anywhere; their pages are American. Every other American topic is about American rules, accounts and protections.
const IDEAS = new Set(["money-overview", "money-spending-plan", "money-investing-basics", "money-investment-types", "money-what-to-invest"]);

// The Kenyan and Nigerian topics are answered from those countries' own regulators and need no American warning.
const KENYA = Object.freeze(["ke-bank-deposit-insurance", "ke-sacco", "ke-mobile-money", "ke-digital-loans", "ke-credit-reference", "ke-saving-investing", "ke-pension-retirement", "ke-tax-personal", "ke-scams-fraud", "ke-chama-groups"]);
const NIGERIA = Object.freeze(["ng-bank-deposit-insurance", "ng-microfinance-cooperatives", "ng-mobile-money-fintech", "ng-digital-loans", "ng-credit-bureaus", "ng-saving-investing", "ng-pension", "ng-tax-personal", "ng-scams-fraud"]);
const LOCAL_TOPICS = new Set([...KENYA, ...NIGERIA]);
// A question about an American topic that a person in Kenya or Nigeria asks without naming a country gets the local answer where there is one (the American topics with no local answer keep the warning below).
const LOCAL_OF = Object.freeze({
  ke: Object.freeze({ "money-bank-account": "ke-bank-deposit-insurance", "money-credit": "ke-credit-reference", "money-costly-borrowing": "ke-digital-loans", "money-retirement-accounts": "ke-pension-retirement", "money-ira": "ke-pension-retirement",
    "money-scams": "ke-scams-fraud", "money-irregular-income": "ke-tax-personal", "money-tax-help": "ke-tax-personal", "money-investment-types": "ke-saving-investing", "money-cash-like": "ke-saving-investing", "money-brokerage-and-kids": "ke-saving-investing" }),
  ng: Object.freeze({ "money-bank-account": "ng-bank-deposit-insurance", "money-credit": "ng-credit-bureaus", "money-costly-borrowing": "ng-digital-loans", "money-retirement-accounts": "ng-pension", "money-ira": "ng-pension",
    "money-scams": "ng-scams-fraud", "money-irregular-income": "ng-tax-personal", "money-tax-help": "ng-tax-personal", "money-investment-types": "ng-saving-investing", "money-cash-like": "ng-saving-investing", "money-brokerage-and-kids": "ng-saving-investing" })
});
// For the investing ideas, the local place to check an offer
const CHECK_AN_OFFER = Object.freeze({
  ke: " To check an investment where you live, ask me how to check one with Kenya's Capital Markets Authority.",
  ng: " To check an investment where you live, ask me how to check one with Nigeria's Securities and Exchange Commission."
});

function outsideNote(country, id) {
  const ideas = IDEAS.has(id);
  const base = ideas
    ? "The ideas here hold anywhere, but the pages are from the United States, and the accounts, protections and taxes where you live may be different, so please check with a bank, regulator or counselor you trust there."
    : "These are United States rules and guidance, from American pages. Where you live, the accounts, protections, taxes and rules are different, so please ask a bank, regulator or counselor you trust there before you decide anything.";
  const pointer = ideas && id !== "money-overview" && CHECK_AN_OFFER[country] ? CHECK_AN_OFFER[country] : "";
  return { text: base + pointer, extra: [] };
}

function moneyAnswer(id, { us = true, country = null } = {}) {
  let topicId = id;
  if (!us && country && LOCAL_OF[country] && LOCAL_OF[country][id]) topicId = LOCAL_OF[country][id];
  const topic = TOPICS[topicId];
  if (!topic) return null;
  const keys = [...topic.sources];
  let lead = "";
  if (!us && topicId !== "money-overview" && !LOCAL_TOPICS.has(topicId)) {
    const note = outsideNote(country, topicId);
    lead = `${note.text} `;
    for (const key of note.extra) if (!keys.includes(key)) keys.push(key);
  }
  const sources = keys.map(key => SOURCES[key]);
  const cited = sources.length ? ` Sources: ${sources.map(source => source.name).join("; ")} (checked ${CHECKED_ON}).` : "";
  return { topic: topicId, title: topic.title, text: `${lead}${topic.text}${cited} ${CLOSINGS[topic.kind]}`, sources };
}

module.exports = Object.freeze({ CHECKED_ON, SOURCES, TOPICS, moneyAnswer });
